/**
 * @jest-environment node
 *
 * `workflows/drive-video-link-sync-by-code.json` is generated by scripts/patch-drive-sync-by-code.py
 * from `workflows/drive-video-link-sync.json`. A demo file named by a 6-char code is looked up in
 * game_info.demo_code and linked + renamed. Anything else, including a code that exists nowhere
 * (a real title like "Racket" is 6 letters), stays on the title-matching path.
 */
import fs from 'fs'
import path from 'path'
import { CODE_ALPHABET, codeFromFileName } from '@/lib/short-code'

const read = (f: string) => JSON.parse(fs.readFileSync(path.join(process.cwd(), f), 'utf8'))
const base = read('workflows/drive-video-link-sync.json')
const wf = read('workflows/drive-video-link-sync-by-code.json')
type N = { name: string; type: string; typeVersion: number; parameters: Record<string, any>; credentials?: any }
const node = (name: string): N => wf.nodes.find((n: N) => n.name === name)
const src = (name: string): string => node(name).parameters.jsCode

type Row = Record<string, any>
// ctx: node name -> one item (json) or an array of items
const run = (name: string, input: Row[], ctx: Record<string, Row | Row[]> = {}): Row[] => {
  const asItems = (v: Row | Row[]) => (Array.isArray(v) ? v : [v]).map(json => ({ json }))
  const $ = (n: string) => {
    if (!(n in ctx)) throw new Error(`no node ${n}`)
    const items = asItems(ctx[n])
    return { first: () => items[0], all: () => items }
  }
  // eslint-disable-next-line @typescript-eslint/no-implied-eval
  const out = new Function('$input', '$', src(name))({ all: () => input.map(json => ({ json })), first: () => ({ json: input[0] }) }, $) as { json: Row }[]
  return out.map(o => o.json)
}

const drive = (name: string, id = name) => ({ id, name, webViewLink: `https://drive.google.com/file/d/${id}/view` })
const FILES = ['K7M2QX.mp4', 'Racket.mp4', 'Some Game.mp4', 'K7M2QX_20mins.mp4'].map(n => drive(n))
const FOLDER = { 'Config2': { folderId: 'FOLDER1' } }

const demoRow = (over: Row = {}) => ({
  code: 'K7M2QX', file_id: 'K7M2QX.mp4', drive_link: 'https://drive.google.com/file/d/K7M2QX.mp4/view',
  demo_game_id: 'g-1', demo_title: 'Nail Box Sort', in_record: false, can_write: true, link_is_this_file: false, ...over,
})
const classify = (rows: Row[], files = FILES) => {
  const split = run('Split Code Files', files)[0]
  return run('Classify Codes', rows, { 'Split Code Files': split })[0]
}

describe('drive-video-link-sync [by-code] workflow', () => {
  it('has its own name and keeps the title path nodes byte-identical to the base file', () => {
    expect(wf.name).toBe('drive-video-link-sync [by-code]')
    for (const n of ['Google Drive Trigger', 'Config2', 'List Drive Files2', 'Parse File Names2', 'Match Titles in DB2',
      'Build Update SQL2', 'Update drive_link2', 'Summary2', 'Log flow_log2']) {
      expect(node(n).parameters).toEqual(base.nodes.find((b: N) => b.name === n).parameters)
    }
  })

  it('is wired List -> Split -> Lookup -> Classify, which feeds the title path first and the code path after', () => {
    const next = (n: string, out = 0) => wf.connections[n].main[out].map((c: { node: string }) => c.node)
    expect(next('List Drive Files2')).toEqual(['Split Code Files'])
    expect(next('Split Code Files')).toEqual(['Lookup Codes'])
    expect(next('Lookup Codes')).toEqual(['Classify Codes'])
    expect(next('Classify Codes')).toEqual(['Title Files', 'Code Notices', 'Write Code Links'])
    expect(next('Title Files')).toEqual(['Parse File Names2'])
    expect(next('Parse File Names2')).toEqual(['Match Titles in DB2'])
    expect(next('Write Code Links')).toEqual(['Plan Renames'])
    expect(next('Plan Renames')).toEqual(['Names Taken'])
    expect(next('Names Taken')).toEqual(['Resolve Names'])
    expect(next('Resolve Names')).toEqual(['Rename Drive File'])
    expect(next('Code Notices')).toEqual(['Log Code Notices', 'Chat Code Notice'])
  })

  it('the code alphabet in the node source equals CODE_ALPHABET in lib/short-code.ts, and the rule gives the same answers', () => {
    for (const name of ['Split Code Files']) {
      const m = src(name).match(/const CODE_ALPHABET = '([^']+)'/)
      expect(m && m[1]).toBe(CODE_ALPHABET)
    }
    const names = ['K7M2QX.mp4', 'k7m2qx.MOV', 'K7M2QX (1).mp4', 'K7M2QX(2).mp4', ' K7M2QX .mp4', 'Racket.mp4', 'Puzzle.mp4',
      'K7M2QX_20mins.mp4', 'K7M2Q.mp4', 'K7M2QXA.mp4', 'K7M2Q0.mp4', 'K7M2QI.mp4', 'Some Game.mp4', 'K7M2QX', 'K7M2QX.tar.mp4']
    const out = run('Split Code Files', names.map(n => drive(n)))[0]
    const codeOf = (n: string) => (out.codeFiles as Row[]).find(c => c.name === n)?.code ?? null
    for (const n of names) expect(codeOf(n)).toBe(codeFromFileName(n))
  })

  describe('Split Code Files', () => {
    it('code branch takes K7M2QX.mp4 and Racket.mp4; the others stay with the title files', () => {
      const out = run('Split Code Files', FILES)[0]
      expect((out.codeFiles as Row[]).map(c => c.name)).toEqual(['K7M2QX.mp4', 'Racket.mp4'])
      expect(out.files).toHaveLength(4)
    })
    it('asks the database for both columns, in one query', () => {
      const sql = run('Split Code Files', FILES)[0].sql as string
      expect(sql).toMatch(/LEFT JOIN game_info d ON to_jsonb\(d\)->>'demo_code' = c\.code/)
      expect(sql).toMatch(/LEFT JOIN game_info r ON to_jsonb\(r\)->>'record_code' = c\.code/)
      // never names the new columns directly: a missing migration 052 must not make the query fail
      expect(sql).not.toMatch(/\b[dr]\.(demo|record)_code\b/)
      expect(sql).toContain('"code":"K7M2QX"')
      expect(sql).toContain('"code":"RACKET"')
    })
    it('still returns a runnable statement when there is no code file', () => {
      const out = run('Split Code Files', [drive('Some Game.mp4')])[0]
      expect(out.sql).toBe('SELECT 1 AS no_codes')
      expect(out.codeFiles).toEqual([])
    })
  })

  describe('Classify Codes', () => {
    it('a known code leaves the title path and is written + renamed', () => {
      const out = classify([demoRow()])
      expect((out.titleFiles as Row[]).map(f => f.name)).toEqual(['Racket.mp4', 'Some Game.mp4', 'K7M2QX_20mins.mp4'])
      expect(out.writes).toEqual([expect.objectContaining({ game_id: 'g-1', file_id: 'K7M2QX.mp4', title: 'Nail Box Sort' })])
      expect(out.notices).toEqual([])
    })

    it('an unknown code is sent back to the title path with no error status', () => {
      const out = classify([demoRow({ code: 'K7M2QX', demo_game_id: null, can_write: false })])
      expect((out.titleFiles as Row[]).map(f => f.name)).toEqual(['K7M2QX.mp4', 'Racket.mp4', 'Some Game.mp4', 'K7M2QX_20mins.mp4'])
      expect(out.notices).toEqual([])
      expect(out.writes).toEqual([])
      expect(out.writeSql).toBe('SELECT 1 AS none')
    })

    it('the real title "Racket" is a code-shaped name: unknown as a code, it reaches Parse File Names2 as a title', () => {
      const out = classify([demoRow({ code: 'RACKET', file_id: 'Racket.mp4', demo_game_id: null, can_write: false })])
      const titles = run('Title Files', [out])
      expect(titles.map(f => f.name)).toContain('Racket.mp4')
      const parsed = run('Parse File Names2', titles)[0]
      expect(parsed.sql as string).toContain('"title":"Racket"')
    })

    it('a code whose game already has a link: link_exists, nothing written, file left alone', () => {
      const out = classify([demoRow({ can_write: false })])
      expect(out.writes).toEqual([])
      expect(out.writeSql).toBe('SELECT 1 AS none')
      expect(out.renames).toEqual([])
      expect(out.notices).toEqual([expect.objectContaining({ status: 'link_exists', code: 'K7M2QX', file: 'K7M2QX.mp4' })])
      expect((out.titleFiles as Row[]).map(f => f.name)).not.toContain('K7M2QX.mp4')
    })

    it('a code found only in record_code: wrong_folder, not code_not_found, nothing written', () => {
      const out = classify([demoRow({ demo_game_id: null, demo_title: null, in_record: true, can_write: false })])
      expect(out.notices).toEqual([expect.objectContaining({ status: 'wrong_folder', code: 'K7M2QX' })])
      expect(out.writes).toEqual([])
      expect((out.titleFiles as Row[]).map(f => f.name)).not.toContain('K7M2QX.mp4')
    })

    it('a code that is a demo code AND a record code: ambiguous_code, nothing written or renamed, file left alone', () => {
      const out = classify([demoRow({ in_record: true })])
      expect(out.notices).toEqual([expect.objectContaining({ status: 'ambiguous_code', code: 'K7M2QX', file: 'K7M2QX.mp4', file_id: 'K7M2QX.mp4' })])
      expect(out.writes).toEqual([])
      expect(out.writeSql).toBe('SELECT 1 AS none')
      expect(out.renames).toEqual([])
      expect((out.titleFiles as Row[]).map(f => f.name)).not.toContain('K7M2QX.mp4')
      // the same holds when the link is already this file (no rename retry either)
      const again = classify([demoRow({ in_record: true, can_write: false, link_is_this_file: true })])
      expect(again.renames).toEqual([])
      expect((again.notices as Row[]).map(n => n.status)).toEqual(['ambiguous_code'])
    })

    it('a link that already points at this very file means only the rename is missing: retried, not reported', () => {
      const out = classify([demoRow({ can_write: false, link_is_this_file: true })])
      expect(out.writes).toEqual([])
      expect(out.renames).toEqual([expect.objectContaining({ game_id: 'g-1' })])
      expect(out.notices).toEqual([])
    })

    it('a second file with the same known code is reported, not written twice', () => {
      const files = [drive('K7M2QX.mp4', 'A'), drive('k7m2qx (1).mp4', 'B')]
      const out = classify([demoRow({ file_id: 'A' })], files)
      expect(out.writes).toHaveLength(1)
      expect(out.notices).toEqual([expect.objectContaining({ status: 'link_exists', file: 'k7m2qx (1).mp4' })])
    })

    it('writes only rows with an empty drive_link, for every evaluation row of the game, and sets drive_date', () => {
      const files = [{ id: 'K7M2QX.mp4', name: 'K7M2QX.mp4', webViewLink: "https://x/it's" }]
      const sql = classify([demoRow()], files).writeSql as string
      expect(sql).toMatch(/UPDATE game_evaluations ge/)
      expect(sql).toMatch(/WHERE ge\.game_id::text = v\.game_id AND COALESCE\(ge\.drive_link, ''\) = ''/)
      expect(sql).toMatch(/drive_date = NOW\(\)/)
      expect(sql).not.toMatch(/ge\.id\s*=/)
      expect(sql).toContain("('g-1', 'https://x/it''s')")
      expect(sql).toMatch(/RETURNING ge\.game_id/)
    })

    it('ignores the filler row a query without codes returns', () => {
      const out = classify([{ no_codes: 1 }], [drive('Some Game.mp4')])
      expect(out.titleFiles).toHaveLength(1)
      expect(out.writeSql).toBe('SELECT 1 AS none')
    })
  })

  describe('a failing code lookup falls back to title matching', () => {
    it('Lookup Codes and Write Code Links continue on error instead of stopping the run', () => {
      expect(node('Lookup Codes').onError).toBe('continueRegularOutput')
      expect(node('Write Code Links').onError).toBe('continueRegularOutput')
    })

    it.each([
      ['an error item', [{ error: 'column "demo_code" does not exist' }]],
      ['an empty result', []],
      ['an empty item', [{}]],
    ])('Classify Codes given %s sends ALL files to the title path, writes nothing, emits no status', (_l, rows) => {
      const out = classify(rows as Row[])
      expect((out.titleFiles as Row[]).map(f => f.name)).toEqual(['K7M2QX.mp4', 'Racket.mp4', 'Some Game.mp4', 'K7M2QX_20mins.mp4'])
      expect(out.writes).toEqual([])
      expect(out.renames).toEqual([])
      expect(out.notices).toEqual([])
      expect(out.writeSql).toBe('SELECT 1 AS none')
    })

    it('end to end after a failed lookup, the title path still gets K7M2QX.mp4', () => {
      const out = classify([{ error: 'boom' }])
      const parsed = run('Parse File Names2', run('Title Files', [out]))[0]
      expect(parsed.sql as string).toContain('"title":"K7M2QX"')
    })

    it('a failed write passes no rename (Plan Renames ends the branch)', () => {
      const w = { code: 'K7M2QX', game_id: 'g-1', title: 'T', file_id: 'F', file_name: 'K7M2QX.mp4', drive_link: 'l' }
      expect(run('Plan Renames', [{ error: 'boom' }], { 'Classify Codes': { renames: [], writes: [w] }, ...FOLDER })).toEqual([])
    })

    it('K7M2Q0.mp4 (code-shaped but 0 is outside the alphabet) is a title file from the start', () => {
      const files = [drive('K7M2Q0.mp4')]
      const split = run('Split Code Files', files)[0]
      expect(split.codeFiles).toEqual([])
      const out = classify([{ no_codes: 1 }], files)
      const parsed = run('Parse File Names2', run('Title Files', [out]))[0]
      expect(parsed.sql as string).toContain('"title":"K7M2Q0"')
    })
  })

  describe('Title Files', () => {
    it('hands the title files over as items, and an empty placeholder when there are none', () => {
      expect(run('Title Files', [{ titleFiles: [drive('a.mp4')] }]).map(f => f.name)).toEqual(['a.mp4'])
      expect(run('Title Files', [{ titleFiles: [] }])).toEqual([{}])
      expect(run('Parse File Names2', [{}])[0]).toEqual({ sql: 'SELECT 1;', totalFiles: 0 })
    })
  })

  describe('rename', () => {
    const writes = (title: string, id = 'g-1', over: Row = {}) => ({
      code: 'K7M2QX', game_id: id, title, file_id: 'F-' + id, file_name: 'K7M2QX.mp4', drive_link: 'l', ...over,
    })
    const plan = (renames: Row[], updated: string[]) =>
      run('Plan Renames', [{ updated }], { 'Classify Codes': { renames, writes: renames }, ...FOLDER })

    it('does nothing (ends the branch) when no write happened', () => {
      expect(plan([writes('Nail Box Sort')], [])).toEqual([])
    })

    it('renames only the games the statement actually updated, keeping the extension', () => {
      const out = plan([writes('Nail Box Sort', 'g-1'), writes('Other', 'g-2')], ['g-1'])[0]
      expect(out.renames).toEqual([expect.objectContaining({ file_id: 'F-g-1', newName: 'Nail Box Sort.mp4' })])
    })

    it('rename-only retries (link already this file) are renamed even though nothing was updated now', () => {
      const out = run('Plan Renames', [{ updated: [] }], {
        'Classify Codes': { renames: [writes('Nail Box Sort')], writes: [] }, ...FOLDER,
      })[0]
      expect(out.renames).toHaveLength(1)
    })

    it('strips / \\ : * ? " < > | from the title', () => {
      const out = plan([writes('A/B\\C:D*E?F"G<H>I|J')], ['g-1'])[0]
      expect((out.renames as Row[])[0].newName).toBe('A B C D E F G H I J.mp4')
    })

    it('falls back to the game_id when the title is empty after cleaning', () => {
      const out = plan([writes('???')], ['g-1'])[0]
      expect((out.renames as Row[])[0].newName).toBe('g-1.mp4')
    })

    it('asks Drive for all planned names in one query, quotes escaped, limited to the folder', () => {
      const q = plan([writes("It's A"), writes('B', 'g-2')], ['g-1', 'g-2'])[0].nameQuery as string
      expect(q).toContain("'FOLDER1' in parents")
      expect(q).toContain("name = 'It\\'s A.mp4'")
      expect(q).toContain("name = 'B.mp4'")
      expect(q).toContain('trashed = false')
    })

    it('appends _<game_id> when the name is already in the folder, or two games share a title in one run', () => {
      const planned = { renames: [
        { file_id: 'F1', game_id: 'g-1', code: 'AAAAAA', oldName: 'AAAAAA.mp4', newName: 'Same.mp4', baseName: 'Same', ext: '.mp4' },
        { file_id: 'F2', game_id: 'g-2', code: 'BBBBBB', oldName: 'BBBBBB.mp4', newName: 'Same.mp4', baseName: 'Same', ext: '.mp4' },
        { file_id: 'F3', game_id: 'g-3', code: 'CCCCCC', oldName: 'CCCCCC.mp4', newName: 'Taken.mp4', baseName: 'Taken', ext: '.mp4' },
      ] }
      const out = run('Resolve Names', [{ name: 'Taken.mp4' }], { 'Plan Renames': planned })
      expect(out.map(o => [o.fileId, o.newName])).toEqual([['F1', 'Same.mp4'], ['F2', 'Same_g-2.mp4'], ['F3', 'Taken_g-3.mp4']])
    })

    it('Names Taken returning nothing is fine (the filler item has no name)', () => {
      const planned = { renames: [{ file_id: 'F1', game_id: 'g-1', code: 'AAAAAA', oldName: 'a', newName: 'X.mp4', baseName: 'X', ext: '.mp4' }] }
      expect(run('Resolve Names', [{}], { 'Plan Renames': planned }).map(o => o.newName)).toEqual(['X.mp4'])
    })

    it('uses the Drive node to rename, with the same credential as the listing', () => {
      const n = node('Rename Drive File')
      expect(n.type).toBe('n8n-nodes-base.googleDrive')
      expect(n.parameters.operation).toBe('update')
      expect(n.parameters.newUpdatedFileName).toBe('={{ $json.newName }}')
      expect(n.credentials).toEqual(node('List Drive Files2').credentials)
    })
  })

  describe('notices', () => {
    const notices = [
      { status: 'link_exists', code: 'K7M2QX', file: 'K7M2QX.mp4', game_id: 'g-1', title: 'Nail Box Sort' },
      { status: 'wrong_folder', code: 'ZZZZZZ', file: 'ZZZZZZ.mp4', game_id: 'g-9', title: 'Rec' },
    ]
    it('makes one flow_log row and one Chat text per notice, with the status as given', () => {
      const out = run('Code Notices', [{}], { 'Classify Codes': { notices } })
      expect(out.map(o => o.status)).toEqual(['link_exists', 'wrong_folder'])
      expect(out.every(o => o.name === 'drive-video-link-sync')).toBe(true)
      expect(JSON.parse(out[0].note)).toMatchObject({ file: 'K7M2QX.mp4', code: 'K7M2QX' })
      expect(out[0].text).toContain('K7M2QX.mp4')
      expect(out[1].text).toMatch(/record/i)
    })
    it('emits nothing when there is nothing to report', () => {
      expect(run('Code Notices', [{}], { 'Classify Codes': { notices: [] } })).toEqual([])
    })
    it('an ambiguous_code notice is logged and posted with its own status and a plain text', () => {
      const amb = [{ status: 'ambiguous_code', code: 'K7M2QX', file: 'K7M2QX.mp4', file_id: 'F1', game_id: 'g-1', title: 'Nail Box Sort' }]
      const out = run('Code Notices', [{}], { 'Classify Codes': { notices: amb } })
      expect(out).toHaveLength(1)
      expect(out[0].status).toBe('ambiguous_code')
      expect(out[0].text).toContain('K7M2QX.mp4')
      expect(out[0].text).toMatch(/both a demo code and a record code/)
      expect(out[0].text).toMatch(/left as it is/)
    })
    it('posts to the agreed Chat space and logs to the same sheet as the existing flow_log node', () => {
      expect(node('Chat Code Notice').parameters.spaceId).toBe('spaces/AAQAYTKWM1I')
      expect(node('Chat Code Notice').credentials).toEqual({ googleApi: { id: '5MOpxh9U04GXBIJp', name: 'HungDT-Minisoos' } })
      for (const n of ['Log Code Notices', 'Log Code Result']) {
        expect(node(n).parameters.documentId).toEqual(node('Log flow_log2').parameters.documentId)
        expect(node(n).parameters.sheetName).toEqual(node('Log flow_log2').parameters.sheetName)
        expect(node(n).credentials).toEqual(node('Log flow_log2').credentials)
      }
    })
  })

  describe('Code Result', () => {
    it('logs how many files were renamed and flags failures', () => {
      const ok = run('Code Result', [{ id: 'F1', name: 'X.mp4' }, { id: 'F2', name: 'Y.mp4' }])[0]
      expect(ok).toMatchObject({ name: 'drive-video-link-sync', status: 'code_linked' })
      expect(JSON.parse(ok.note)).toMatchObject({ renamed: 2, failed: 0 })
      const bad = run('Code Result', [{ id: 'F1', name: 'X.mp4' }, { error: 'boom' }])[0]
      expect(bad.status).toBe('rename_failed')
    })
  })

  it('the live-safe settings: the new workflow carries nothing that would run it', () => {
    expect(wf.active).toBeUndefined()
  })
})
